--
-- Structure de la table `facturesuppliers`
--

CREATE TABLE `facturesuppliers` (
  `id` int(11) NOT NULL,
  `company` int(11) NOT NULL DEFAULT 0,
  `code` varchar(255) NOT NULL DEFAULT '',
  `supplier` int(11) NOT NULL DEFAULT 0,
  `client` int(11) NOT NULL DEFAULT 0,
  `refbc` varchar(255) NOT NULL DEFAULT '',
  `price` double NOT NULL DEFAULT 0,
  `tva` double NOT NULL DEFAULT 0,
  `rastva` double NOT NULL DEFAULT 0,
  `price2` double NOT NULL DEFAULT 0,
  `tva2` double NOT NULL DEFAULT 0,
  `currency` varchar(255) NOT NULL DEFAULT 'DH',
  `state` varchar(255) NOT NULL DEFAULT 'Non payée',
  `note` text NOT NULL DEFAULT '',
  `delay` int(11) NOT NULL DEFAULT 0,
  `retard` int(11) NOT NULL DEFAULT 0,
  `retardpaid` varchar(255) NOT NULL DEFAULT '',
  `dateretard` varchar(255) NOT NULL DEFAULT '',
  `stateras` varchar(255) NOT NULL DEFAULT 'Non payée',
  `retardras` int(11) NOT NULL DEFAULT 0,
  `datepaidras` varchar(255) NOT NULL DEFAULT '',
  `attachmentras` varchar(255) NOT NULL DEFAULT '',
  `attachments` text NOT NULL DEFAULT '',
  `user` int(11) NOT NULL DEFAULT 0,
  `datepaid` varchar(255) NOT NULL DEFAULT '',
  `datedue` varchar(255) NOT NULL DEFAULT '',
  `dateadd` varchar(255) NOT NULL DEFAULT '',
  `trash` int(11) NOT NULL DEFAULT 0,
  `payments` double NOT NULL DEFAULT 0,
  `devispayments` double NOT NULL DEFAULT 0,
  `recalldate` varchar(255) NOT NULL DEFAULT '',
  `recallnote` text NOT NULL DEFAULT '',
  `labels` text NOT NULL DEFAULT ''
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

